      es: ["Superficie: 110 hectáreas", "Inauguración: 1929", "Arquitecto: Joseph Marrast", "Número de especies de árboles: más de 100", "Longitud de las avenidas: aprox. 5 km", "Altura del Belvedere: 80 m sobre el nivel del mar"],
