      en: ["Ghorfas originally functioned as multi-story grain storage cells.", "Medenine served as a key filming location for the Star Wars saga.", "Some of the ksour structures in the park date back to the 17th century.", "The mud-brick architecture provides natural insulation from heat.", "Originally, there were over 6,000 such storage chambers in Medenine.", "The park educates visitors on traditional Berber crafting techniques."],
